// Shared loader for manifest + metadata (optional)
async function EV_loadPortfolioData(){
  // 1) manifest is required (generated by script)
  let manifest = { items: [] };
  try{
    const r = await fetch("assets/portfolio.manifest.json", { cache: "no-store" });
    if(r.ok) manifest = await r.json();
  }catch(e){}

  const items = Array.isArray(manifest) ? manifest : (manifest.items || []);

  // 2) metadata optional (JSON preferred)
  let meta = { files: {} };
  try{
    const r2 = await fetch("assets/portfolio.meta.json", { cache: "no-store" });
    if(r2.ok) meta = await r2.json();
  }catch(e){}

  // 3) fallback: CSV metadata (optional) -> only used if JSON empty and CSV exists
  if(meta && meta.files && Object.keys(meta.files).length === 0){
    try{
      const r3 = await fetch("assets/portfolio.meta.csv", { cache:"no-store" });
      if(r3.ok){
        const text = await r3.text();
        meta = { files: EV_parseMetaCSV(text) };
      }
    }catch(e){}
  }

  return { items, meta: (meta && meta.files) ? meta.files : {} };
}

// Very small CSV parser: file,title,client,service,year,tags,url
function EV_parseMetaCSV(text){
  const lines = text.split(/\r?\n/).filter(l => l.trim().length);
  if(lines.length < 2) return {};
  const header = lines[0].split(",").map(s=>s.trim().toLowerCase());
  const idx = (name)=> header.indexOf(name);
  const f = {};
  for(let i=1;i<lines.length;i++){
    const row = EV_splitCSVLine(lines[i]);
    const file = row[idx("file")]?.trim();
    if(!file) continue;
    f[file] = {
      title: row[idx("title")]?.trim() || "",
      client: row[idx("client")]?.trim() || "",
      service: row[idx("service")]?.trim() || "",
      year: Number(row[idx("year")] || "") || "",
      tags: (row[idx("tags")] || "").split("|").map(s=>s.trim()).filter(Boolean),
      url: row[idx("url")]?.trim() || ""
    };
  }
  return f;
}

// Splits a CSV line supporting simple quoted fields.
function EV_splitCSVLine(line){
  const out = [];
  let cur = "", inQ = false;
  for(let i=0;i<line.length;i++){
    const ch = line[i];
    if(ch === '"' ){
      if(inQ && line[i+1] === '"'){ cur += '"'; i++; }
      else inQ = !inQ;
      continue;
    }
    if(ch === "," && !inQ){
      out.push(cur); cur = ""; continue;
    }
    cur += ch;
  }
  out.push(cur);
  return out;
}

function EV_titleFromFilename(file){
  const name = file.replace(/\.[^/.]+$/, '');
  const cleaned = name
    .replace(/^([a-z]+)(__|-|_)/i,'')
    .replace(/__/g,' ')
    .replace(/[-_]+/g,' ')
    .trim();
  return cleaned ? cleaned.replace(/\b\w/g, c => c.toUpperCase()) : "Proyecto";
}

function EV_categoryFromFilename(file){
  const lower = file.toLowerCase();
  const known = ["redes","promo","marca","web","musica"];
  const m = lower.match(/^([a-z]+)(?:__|-|_)/);
  if(m && known.includes(m[1])) return m[1];
  return "all";
}

function EV_buildCard({src, title, cat, metaText, url}){
  const el = document.createElement("div");
  el.className = "work reveal";
  el.dataset.cat = cat || "all";
  el.dataset.full = src;

  const tag = (cat || "portfolio").toUpperCase();
  const sub = metaText ? metaText : tag;

  el.innerHTML = `
    <img src="${src}" alt="${title}">
    <div class="meta">
      <div class="title"><strong>${title}</strong><span>${sub}</span></div>
      <div class="tag">${tag}</div>
    </div>
  `;

  // click: open modal; if url exists, open in new tab with middle click support
  el.addEventListener("click", ()=>{
    window.EV_openModal?.(src);
  });

  if(url){
    el.style.cursor = "pointer";
    el.addEventListener("auxclick", (e)=>{
      if(e.button === 1) window.open(url, "_blank");
    });
  }

  return el;
}

// After render: quick reveal
function EV_forceReveal(){
  setTimeout(()=> document.querySelectorAll('.reveal').forEach(el=> el.classList.add('on')), 60);
}
